        self
    }
}

impl<B> RouteFuture<B, Infallible>
where
    B: HttpBody + Send + 'static,
{
    pub(super) fn empty() -> Self {
        Self {
            kind: RouteFutureKind::Response { response: None },
            strip_body: false,
            allow_header: None,
        }
    }

    pub(super) fn call_router(self, router: &super::Router<B>, mut req: Request<B>) -> Self {
        let strip_body = self.strip_body;
        let allow_header = self.allow_header;

        let path = req.uri().path().to_owned();

        match router.node.at(&path) {
            Ok(match_) => router.call_route(match_, req),
            Err(err) => {
                let uri = req.uri();
                let query = uri.query();
                let scheme = uri.scheme().cloned();
                let authority = uri.authority().cloned();

                let new_path = match err {
                    MatchError::MissingTrailingSlash => Some(format!("{}/", path)),
                    MatchError::ExtraTrailingSlash => path.strip_suffix('/').map(str::to_owned),
                    MatchError::NotFound => None,
                };

                if let Some(new_path) = new_path {
                    let mut new_path_and_query = new_path;
                    if let Some(query) = query {
                        new_path_and_query.push('?');
                        new_path_and_query.push_str(query);
                    }

                    let mut parts = http::uri::Parts::default();
                    parts.scheme = scheme;
                    parts.authority = authority;
                    parts.path_and_query = Some(new_path_and_query.parse().unwrap());

                    if let Some(new_uri) = Uri::from_parts(parts).ok() {
                        let redirect = Redirect::permanent(&new_uri.to_string());
                        let mut future = RouteFuture::from_response(Redirect::build_response(
                            redirect.status_code,
                            redirect.location,
                        ));
                        future.strip_body = strip_body;
                        future.allow_header = allow_header;
                        return future;
                    }
                }

                match &router.fallback {
                    super::Fallback::Default(inner) => inner.clone().call(req),
                    super::Fallback::Custom(inner) => inner.clone().call(req),
                }
            }
        }
    }
}

impl<B, E> Future for RouteFuture<B, E>
where
    B: HttpBody,
{
    type Output = Result<Response, E>;

    #[inline]
    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        #[derive(Clone, Copy)]
        struct AlreadyPassedThroughRouteFuture;

        let this = self.project();

        let mut res = match this.kind.project() {
            RouteFutureKindProj::Future { future } => match future.poll(cx) {
                Poll::Ready(Ok(res)) => res,
                Poll::Ready(Err(err)) => return Poll::Ready(Err(err)),
                Poll::Pending => return Poll::Pending,
            },
            RouteFutureKindProj::Response { response } => {
                response.take().expect("future polled after completion")
            }
        };

        if res
            .extensions()
            .get::<AlreadyPassedThroughRouteFuture>()
            .is_some()
        {
            return Poll::Ready(Ok(res));
        } else {
            res.extensions_mut().insert(AlreadyPassedThroughRouteFuture);
        }

        set_allow_header(&mut res, this.allow_header);

        // make sure to set content-length before removing the body
        set_content_length(&mut res);

        let res = if *this.strip_body {
            res.map(|_| boxed(Empty::new()))
        } else {
            res
        };

        Poll::Ready(Ok(res))
    }
}

fn set_allow_header<B>(res: &mut Response<B>, allow_header: &mut Option<Bytes>) {
    match allow_header.take() {
        Some(allow_header) if !res.headers().contains_key(header::ALLOW) => {
            res.headers_mut().insert(
                header::ALLOW,
                HeaderValue::from_maybe_shared(allow_header).expect("invalid `Allow` header"),
            );
        }
        _ => {}
    }
}

fn set_content_length<B>(res: &mut Response<B>)
where
    B: HttpBody,
{
    if res.headers().contains_key(CONTENT_LENGTH) {
        return;
    }

    if let Some(size) = res.size_hint().exact() {
        let header_value = if size == 0 {
            #[allow(clippy::declare_interior_mutable_const)]
            const ZERO: HeaderValue = HeaderValue::from_static("0");

            ZERO
        } else {
            let mut buffer = itoa::Buffer::new();
            HeaderValue::from_str(buffer.format(size)).unwrap()
        };

        res.headers_mut().insert(CONTENT_LENGTH, header_value);
    }
}

